INSERT INTO item_definitions(code,display_name,asset_type_code,stackable,metadata_json,active,version) VALUES('ITEM-HOME-FURNITURE-UNBIND-TICKET','가구귀속해제권🛋️(/가구해제 숫자)','ITEM',TRUE,JSON_OBJECT('source','legacy-main.js','legacyExactName','가구귀속해제권🛋️(/가구해제 숫자)','gate8Snapshot','pending'),TRUE,1) ON DUPLICATE KEY UPDATE display_name=VALUES(display_name),stackable=TRUE,metadata_json=VALUES(metadata_json),active=TRUE,version=version+1;
CREATE TABLE home_furniture_unequip_operations(operation_id BIGINT UNSIGNED NOT NULL,player_id BIGINT UNSIGNED NOT NULL,furniture_instance_id BIGINT UNSIGNED NOT NULL,ticket_item_id BIGINT UNSIGNED NOT NULL,requested_index BIGINT UNSIGNED NOT NULL,placed_count_before BIGINT UNSIGNED NOT NULL,placed_count_after BIGINT UNSIGNED NOT NULL,bag_count_before BIGINT UNSIGNED NOT NULL,bag_count_after BIGINT UNSIGNED NOT NULL,bag_limit BIGINT UNSIGNED NOT NULL,ticket_before BIGINT UNSIGNED NOT NULL,ticket_after BIGINT UNSIGNED NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT UTC_TIMESTAMP(3),PRIMARY KEY(operation_id),KEY idx_home_furniture_unequip_player_created(player_id,created_at),KEY idx_home_furniture_unequip_instance(furniture_instance_id),CONSTRAINT fk_home_furniture_unequip_operation FOREIGN KEY(operation_id) REFERENCES operations(id) ON DELETE RESTRICT,CONSTRAINT fk_home_furniture_unequip_player FOREIGN KEY(player_id) REFERENCES players(id) ON DELETE RESTRICT,CONSTRAINT fk_home_furniture_unequip_instance FOREIGN KEY(furniture_instance_id) REFERENCES furniture_inventory_instances(id) ON DELETE RESTRICT,CONSTRAINT fk_home_furniture_unequip_ticket FOREIGN KEY(ticket_item_id) REFERENCES item_definitions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
